"""Render the offline project dashboard from the versioned state file."""
import html
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
state = json.loads((ROOT / 'docs/ai-context/project_state.json').read_text())
esc = lambda value: html.escape(str(value))
verified = sum(m['status'] == 'Verified' for m in state['milestones'])
percent = f"{100 * verified / len(state['milestones']):g}"
cards = ''.join(f'<article><h3>{esc(m["name"])}</h3><p class="badge">{esc(m["status"])}</p><p>{esc(m["criteria"])}</p></article>' for m in state['milestones'])
items = lambda values: ''.join(f'<li>{esc(v)}</li>' for v in values)
page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>School-CMS · Project status</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#eef3f7;color:#152d41;font:16px/1.6 system-ui,sans-serif}}main{{max-width:1140px;margin:auto;padding:32px 20px}}header,section{{background:white;padding:26px;border-radius:16px;margin-bottom:22px;border:1px solid #dce5ec}}h1{{font-size:clamp(28px,4vw,44px);line-height:1.15;margin:12px 0}}h2{{font-size:23px}}.eyebrow{{color:#28756e;font-weight:700;letter-spacing:.06em}}.metrics,.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}}article{{background:#f6f9fc;border:1px solid #dee6ef;border-radius:12px;padding:20px}}.big{{font-size:36px;font-weight:750;color:#176b60}}.badge{{display:inline-block;background:#e1edf8;color:#234b70;border-radius:24px;padding:4px 12px;font-weight:650}}p{{margin:8px 0}}progress{{width:100%;height:16px;accent-color:#176b60}}a{{color:#146b80}}footer{{color:#5d6d7a}}:focus-visible{{outline:3px solid #c57718}}li{{margin-bottom:7px}}
</style></head><body><main><header><p class="eyebrow">SCHOOL-CMS / DELIVERY CHECKPOINT</p><h1>A coherent school operating platform</h1><p>{esc(state['objective'])}</p><p>Updated {esc(state['updated'])} · {esc(state['phase'])}</p><div class="metrics"><div><p class="big">{percent}%</p><p>Verified implementation milestones</p></div><div><p class="big">{esc(state['tests']['passed'])}</p><p>Automated tests passed</p></div><div><p class="badge">{esc(state['readiness'])}</p><p>Production release: Not started</p></div></div><progress value="{percent}" max="100">{percent}%</progress><p>Scoring: {verified} of {len(state['milestones'])} equally weighted implementation milestones meet the documented local acceptance criteria. This percentage does not measure production readiness.</p></header><section><h2>Milestones and acceptance criteria</h2><div class="grid">{cards}</div></section><section><h2>Latest verification</h2><ul>{items(state['tests']['commands'])}</ul><p>{esc(state['tests']['environment'])}</p></section><section><h2>Known limitations and risks</h2><ul>{items(state['limitations'])}</ul></section><section><h2>Decisions</h2><ul>{items(state['decisions'])}</ul></section><section><h2>Next actions</h2><ol>{items(state['next_actions'])}</ol></section><section><h2>Scope</h2><p>MVP: identity, admissions, enrollment history, authorization, teaching, attendance, assessments and fees in staged increments.</p><p>Later: guardian portal, transport, library, HR/payroll, inventory, integrations and SaaS billing.</p><p><a href="09_NEXT_ACTIONS.md">Next-action handoff</a> · <a href="08_TEST_RELEASE_STATUS.md">Release evidence</a></p></section><footer>Generated from project_state.json. Offline readable; no external dependencies.</footer></main></body></html>'''
(ROOT / 'docs/ai-context/PROJECT_STATUS.html').write_text(page)
print(f'Status regenerated: {verified}/{len(state["milestones"])} = {percent}%')
